#!/usr/bin/python3

import pyrob.core as rob
import random
from pyrob.tasks import check_filled_cells, find_cells_to_be_filled

# Порядок вариантов: один раз перемешиваем при загрузке модуля — без повторений в пределах 0..5
_variant_order = list(range(6))
random.shuffle(_variant_order)

class Task:
    CHECKS = 3

    def load_level(self, n):
        idx = _variant_order[n % len(_variant_order)]
        if idx == 0:
            rob.set_field_size(3, 12)
            rob.set_cell_type(1, 1, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 2, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 3, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 4, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 5, rob.CELL_TO_BE_FILLED)
            rob.goto(1, 1)
            rob.put_wall(bottom=True)
            rob.goto(1, 2)
            rob.put_wall(bottom=True)
            rob.goto(1, 3)
            rob.put_wall(bottom=True)
            rob.goto(1, 4)
            rob.put_wall(bottom=True)
            rob.goto(1, 5)
            rob.put_wall(bottom=True)
            rob.set_parking_cell(1, 0)
            rob.goto(1, 0)
        elif idx == 1:
            rob.set_field_size(3, 5)
            rob.set_cell_type(1, 1, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 2, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 3, rob.CELL_TO_BE_FILLED)
            rob.goto(1, 1)
            rob.put_wall(bottom=True)
            rob.goto(1, 2)
            rob.put_wall(bottom=True)
            rob.goto(1, 3)
            rob.put_wall(bottom=True)
            rob.set_parking_cell(1, 0)
            rob.goto(1, 0)
        elif idx == 2:
            rob.set_field_size(3, 10)
            rob.set_cell_type(1, 1, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 2, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 3, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 4, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 5, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 6, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 7, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 8, rob.CELL_TO_BE_FILLED)
            rob.goto(1, 1)
            rob.put_wall(bottom=True)
            rob.goto(1, 2)
            rob.put_wall(bottom=True)
            rob.goto(1, 3)
            rob.put_wall(bottom=True)
            rob.goto(1, 4)
            rob.put_wall(bottom=True)
            rob.goto(1, 5)
            rob.put_wall(bottom=True)
            rob.goto(1, 6)
            rob.put_wall(bottom=True)
            rob.goto(1, 7)
            rob.put_wall(bottom=True)
            rob.goto(1, 8)
            rob.put_wall(bottom=True)
            rob.set_parking_cell(1, 0)
            rob.goto(1, 0)
        elif idx == 3:
            rob.set_field_size(3, 9)
            rob.set_cell_type(1, 1, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 2, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 3, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 4, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 5, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 6, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 7, rob.CELL_TO_BE_FILLED)
            rob.goto(1, 1)
            rob.put_wall(bottom=True)
            rob.goto(1, 2)
            rob.put_wall(bottom=True)
            rob.goto(1, 3)
            rob.put_wall(bottom=True)
            rob.goto(1, 4)
            rob.put_wall(bottom=True)
            rob.goto(1, 5)
            rob.put_wall(bottom=True)
            rob.goto(1, 6)
            rob.put_wall(bottom=True)
            rob.goto(1, 7)
            rob.put_wall(bottom=True)
            rob.set_parking_cell(1, 0)
            rob.goto(1, 0)
        elif idx == 4:
            rob.set_field_size(3, 8)
            rob.set_cell_type(1, 1, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 2, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 3, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 4, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 5, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 6, rob.CELL_TO_BE_FILLED)
            rob.goto(1, 1)
            rob.put_wall(bottom=True)
            rob.goto(1, 2)
            rob.put_wall(bottom=True)
            rob.goto(1, 3)
            rob.put_wall(bottom=True)
            rob.goto(1, 4)
            rob.put_wall(bottom=True)
            rob.goto(1, 5)
            rob.put_wall(bottom=True)
            rob.goto(1, 6)
            rob.put_wall(bottom=True)
            rob.set_parking_cell(1, 0)
            rob.goto(1, 0)
        elif idx == 5:
            rob.set_field_size(3, 6)
            rob.set_cell_type(1, 1, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 2, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 3, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(1, 4, rob.CELL_TO_BE_FILLED)
            rob.goto(1, 1)
            rob.put_wall(bottom=True)
            rob.goto(1, 2)
            rob.put_wall(bottom=True)
            rob.goto(1, 3)
            rob.put_wall(bottom=True)
            rob.goto(1, 4)
            rob.put_wall(bottom=True)
            rob.set_parking_cell(1, 0)
            rob.goto(1, 0)

        self.cells_to_fill = find_cells_to_be_filled()

    def check_solution(self):
        return check_filled_cells(self.cells_to_fill) and rob.is_parking_point()
